package com.nexus.access.backend.auth;
import java.util.Locale; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import com.nexus.access.backend.exception.*; import com.nexus.access.backend.user.*;
@Service @Transactional public class AuthService {private final UserRepository users;private final PasswordEncoder passwords;private final JwtService jwt;private final RefreshTokenService refresh;public AuthService(UserRepository u,PasswordEncoder p,JwtService j,RefreshTokenService r){users=u;passwords=p;jwt=j;refresh=r;} public UserResponseDTO register(RegisterRequest r){String email=r.email().trim().toLowerCase(Locale.ROOT);if(users.existsByEmailIgnoreCase(email))throw new DuplicateResourceException("Email already exists");User u=new User();u.setFirstName(r.firstName().trim());u.setLastName(r.lastName().trim());u.setEmail(email);u.setPasswordHash(passwords.encode(r.password()));u.setRole("USER");return dto(users.save(u));} public LoginResponse login(LoginRequest r){User u=users.findByEmailIgnoreCase(r.email().trim().toLowerCase(Locale.ROOT)).filter(user->user.isActive()).filter(x->passwords.matches(r.password(),x.getPasswordHash())).orElseThrow(InvalidCredentialsException::new);return tokens(u);} public LoginResponse refresh(String raw){return tokens(refresh.consume(raw));} public void logout(String raw){refresh.revoke(raw);} private LoginResponse tokens(User u){return new LoginResponse(jwt.create(u),refresh.issue(u),"Bearer",jwt.expiration());} private UserResponseDTO dto(User u){return new UserResponseDTO(u.getId(),u.getFirstName(),u.getLastName(),u.getEmail(),u.getRole(),u.isActive(),u.getCreatedAt(),u.getUpdatedAt());}}
